<?php namespace App\Filament\Resources\AcademicOrderResource\Pages;use App\Filament\Resources\AcademicOrderResource;use App\Services\PeriodGuard;use Filament\Resources\Pages\CreateRecord;class CreateAcademicOrder extends CreateRecord{protected static string $resource=AcademicOrderResource::class;protected function mutateFormDataBeforeCreate(array $data):array{$p=request()->attributes->get('academic_period');abort_unless($p,422);PeriodGuard::writable($p->id);$data['academic_period_id']=$p->id;$data['created_by']=auth()->id();return $data;}}